import{_ as d,o as a,c as r,a2 as e}from"./chunks/framework.mRCPFc5l.js";const b=JSON.parse('{"title":"10. 矿车工作站","description":"","frontmatter":{},"headers":[],"relativePath":"minecart.md","filePath":"minecart.md"}'),l={name:"minecart.md"};function o(i,t,n,h,s,c){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="_10-矿车工作站" tabindex="-1">10. 矿车工作站 <a class="header-anchor" href="#_10-矿车工作站" aria-label="Permalink to &quot;10. 矿车工作站&quot;">​</a></h1><h2 id="_10-1-基本操作" tabindex="-1">10.1 基本操作 <a class="header-anchor" href="#_10-1-基本操作" aria-label="Permalink to &quot;10.1 基本操作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>效果</th></tr></thead><tbody><tr><td>潜行 + 右键空矿车（手持方块）</td><td>把方块装到矿车上，变成工作站矿车</td></tr><tr><td>右键工作站矿车</td><td>打开对应界面（工作台/容器等）</td></tr><tr><td>潜行 + 右键工作站矿车</td><td>拆下方块，矿车恢复为空矿车</td></tr></tbody></table><p>矿车可以像普通矿车一样被推动、上下坡和运输。</p><h2 id="_10-2-支持的工作站" tabindex="-1">10.2 支持的工作站 <a class="header-anchor" href="#_10-2-支持的工作站" aria-label="Permalink to &quot;10.2 支持的工作站&quot;">​</a></h2><p>本服 <code>allow-all-blocks: true</code>：除基岩、屏障外，<strong>几乎所有方块都能放上矿车</strong>。下表是有实际交互功能的类型；其他方块会变成装饰矿车（右键没有界面，仍可拆下）。</p><table tabindex="0"><thead><tr><th>方块</th><th>效果</th></tr></thead><tbody><tr><td>工作台</td><td>打开 3×3 合成</td></tr><tr><td>砂轮</td><td>打开砂轮界面</td></tr><tr><td>织布机</td><td>打开织布机界面</td></tr><tr><td>制图台</td><td>打开制图台界面</td></tr><tr><td>锻造台</td><td>打开锻造界面</td></tr><tr><td>切石机</td><td>打开切石机界面</td></tr><tr><td>附魔台</td><td>打开附魔界面</td></tr></tbody></table><h2 id="_10-3-容器矿车" tabindex="-1">10.3 容器矿车 <a class="header-anchor" href="#_10-3-容器矿车" aria-label="Permalink to &quot;10.3 容器矿车&quot;">​</a></h2><p>支持：木桶、投掷器、陷阱箱、潜影盒、合成器。</p><ul><li>右键打开容器，可正常存取。</li><li>拆下时容器内的物品会全部掉到地上，容器以<strong>空白物品</strong>放进背包（<code>container-pickup-policy: DROP</code>）；请先清空再拆。</li><li>陷阱箱仍然是陷阱箱，打开会触发红石信号。</li></ul><h2 id="_10-4-特殊矿车" tabindex="-1">10.4 特殊矿车 <a class="header-anchor" href="#_10-4-特殊矿车" aria-label="Permalink to &quot;10.4 特殊矿车&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方块</th><th>行为</th></tr></thead><tbody><tr><td>发射器</td><td>9 格容器；矿车驶过<strong>充能的激活铁轨</strong>时随机弹出 1 个物品，约 2 秒一次</td></tr><tr><td>铁砧</td><td>可当移动铁砧使用；按原版铁砧规则受损（每次使用约 12% 概率降级/损毁）</td></tr><tr><td>普通熔炉</td><td>变成原版熔炉矿车，可推动、可烧炼</td></tr><tr><td>烟熏炉 / 高炉 / 酿造台</td><td>仅外观，不提供对应功能</td></tr><tr><td>箱子/漏斗/熔炉/TNT/命令方块</td><td>放上空矿车后直接变成对应原版矿车；可正常使用，但<strong>不能拆回方块</strong>（防止刷物品）</td></tr></tbody></table><h2 id="_10-5-限制" tabindex="-1">10.5 限制 <a class="header-anchor" href="#_10-5-限制" aria-label="Permalink to &quot;10.5 限制&quot;">​</a></h2><ul><li>不能骑乘工作站矿车。</li><li>拆下工作站矿车需要潜行右键；普通右键是打开界面。</li><li>容器矿车拆下时物品会散落，建议在安全处操作。</li><li>原版特殊矿车（箱子、漏斗、TNT 等）放下后无法收回，放置前想清楚。</li><li>在他人领地内放置、拆下或打开矿车方块会被领地保护拦截；发射器矿车在禁止生物破坏方块的领地里也不会弹出物品。</li></ul>',14)])])}const u=d(l,[["render",o]]);export{b as __pageData,u as default};
